export function validateContinuation(input={}){const finite=(v)=>{if(typeof v==='number'&&!Number.isFinite(v))throw Error('Continuation values must be finite');if(v&&typeof v==='object')for(const x of Object.values(v))finite(x);};for(const[k,v]of Object.entries(input))if(k.startsWith('continuation'))finite(v);const f={...continuationDefaults,...input};for(const k of ['continuationSceneDurations','continuationSourceBindings','continuationFullSources','continuationLayerEdits'])if(!f[k]||typeof f[k]!=='object'||Array.isArray(f[k]))throw Error('Use an object for '+k);for(const[k,v]of Object.entries(continuationDefaults))if(typeof v==='number'&&!Number.isFinite(f[k]))throw Error('Use finite continuation parameter '+k);if(f.continuationRate<.05||f.continuationRate>4)throw Error('Continuation rate must be 0.05–4');for(const [id,v]of Object.entries(f.continuationSceneDurations||{}))if(!Number.isFinite(v)||v<.05||v>300)throw Error('Scene duration must be 0.05–300 seconds: '+id);for(const [id,e]of Object.entries(f.continuationLayerEdits||{})){if(!e||typeof e!=='object'||Array.isArray(e))throw Error('Use a layer object: '+id);sampleObjectMotion(0,e.motion||{});for(const k of ['x','y','scale','rotation','opacity','depth','blur','brightness'])if(e[k]!==undefined&&(!Number.isFinite(e[k])||['scale','depth'].includes(k)&&e[k]<=0))throw Error('Invalid layer transform '+id+'.'+k);}return f;}
export function continuationDuration(input={}){const f={...continuationDefaults,...input};return continuationStages.reduce((n,s)=>n+(f.continuationSceneDurations[s.id]??s.duration),0)/f.continuationRate;}
