export function continuationState(age,input={}){const f={...continuationDefaults,...input},clock=Math.max(0,age)*f.continuationRate;let cursor=0,s=continuationStages.at(-1),q=1;for(const row of continuationStages){const d=f.continuationSceneDurations[row.id]??row.duration;if(clock<cursor+d){s=row;q=clamp((clock-cursor)/d);break;}cursor+=d;}return {id:s.id,label:s.label,source:mix(s.from,s.to,q),local:age,phase:q,duration:continuationDuration(f),active:f.continuationEnabled&&age>=0&&age<=continuationDuration(f)};}
